mapper.update:
UPDATE TB_CHLC001
   SET VER_NO        = #{h.versionNo},
       LAST_UPD_TYPE = #{h.lastUpdateType},
       LAST_SEND_DT  = #{h.lastSendDate},
       STATUS        = #{h.status},
       UPD_DT        = NOW(),
       UPD_ID        = #{h.writer.updUserId}
 WHERE CP_ID = #{h.cpId}
   AND CS_ID = #{h.csId}

mapper.select:
SELECT CP_ID, CS_ID, VER_NO, LAST_UPD_TYPE, LAST_SEND_DT, STATUS,
       REG_DT, REG_ID, UPD_DT, UPD_ID
  FROM TB_CHLC001
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}
 LIMIT 1

mapper.delete:
DELETE FROM TB_CHLC001
 WHERE CP_ID = #{cpId}
   AND CS_ID = #{csId}

